using System.Text.Json;
namespace Bliss.Domain.CommandGateway;
public sealed record GatewayTaskPolicy(bool Enabled,Guid TenantId,Guid AgentId,Guid ExecutiveAgentId,Guid EngineeringAgentId);
public sealed record GatewayTaskSnapshot(string Stage,int Turns,Guid? LastMessageId,string? CommitHash,string? EvidenceHash,int? Passed,int? Failed,string? Verdict);
public static class GatewayTaskLoop
{
 public static void Authorize(GatewayPrincipal p,GatewayTaskPolicy policy){if(!policy.Enabled||!p.Authenticated||p.TenantId==Guid.Empty||p.AgentId==Guid.Empty||p.TenantId!=policy.TenantId||p.AgentId!=policy.AgentId||policy.ExecutiveAgentId==Guid.Empty||policy.EngineeringAgentId==Guid.Empty||policy.ExecutiveAgentId==policy.EngineeringAgentId||p.AgentId!=policy.ExecutiveAgentId&&p.AgentId!=policy.EngineeringAgentId)throw new UnauthorizedAccessException("Distinct registered local task roles required.");}
 public static GatewayTaskSnapshot Advance(GatewayTaskSnapshot state,GatewayMessageType type,Guid message,Guid? cause,Guid sender,Guid recipient,GatewayTaskPolicy policy,JsonElement payload)
 {
  if(state.Turns>=8||cause!=state.LastMessageId)throw new InvalidOperationException("Bounded sequential task causation required.");
  var expected=state.Stage switch{"NEW"=>GatewayMessageType.DefectReport,"DETECTED"=>GatewayMessageType.TaskAssignment,"ASSIGNED"=>GatewayMessageType.FixProposal,"CORRECTION_PROPOSED"=>GatewayMessageType.TestRequest,"TEST_REQUESTED"=>GatewayMessageType.TestResult,"TEST_REPORTED"=>GatewayMessageType.EvidenceSubmission,"EVIDENCE_SUBMITTED"=>GatewayMessageType.ReviewVerdict,"REVIEWED"=>GatewayMessageType.ApprovalRequest,_=>throw new InvalidOperationException("Known task stage required.")};
  if(type!=expected)throw new InvalidOperationException("Task transition is out of order.");var executive=type is GatewayMessageType.DefectReport or GatewayMessageType.TaskAssignment or GatewayMessageType.ReviewVerdict or GatewayMessageType.ApprovalRequest;var actor=executive?policy.ExecutiveAgentId:policy.EngineeringAgentId;var peer=executive?policy.EngineeringAgentId:policy.ExecutiveAgentId;if(sender!=actor||recipient!=peer)throw new UnauthorizedAccessException("Task role/peer mismatch; engineering cannot self-review.");
  var next=state with{Turns=state.Turns+1,LastMessageId=message,Stage=type switch{GatewayMessageType.DefectReport=>"DETECTED",GatewayMessageType.TaskAssignment=>"ASSIGNED",GatewayMessageType.FixProposal=>"CORRECTION_PROPOSED",GatewayMessageType.TestRequest=>"TEST_REQUESTED",GatewayMessageType.TestResult=>"TEST_REPORTED",GatewayMessageType.EvidenceSubmission=>"EVIDENCE_SUBMITTED",GatewayMessageType.ReviewVerdict=>"REVIEWED",_=>"APPROVAL_REQUESTED"}};
  if(type==GatewayMessageType.FixProposal)next=next with{CommitHash=Hash(payload,"commit",40,false)};
  if(type is GatewayMessageType.TestRequest or GatewayMessageType.TestResult or GatewayMessageType.EvidenceSubmission or GatewayMessageType.ReviewVerdict or GatewayMessageType.ApprovalRequest){if(Hash(payload,"commit",40,false)!=state.CommitHash)throw new InvalidOperationException("Exact correction commit required.");}
  if(type==GatewayMessageType.TestResult){var passed=Count(payload,"passed");var failed=Count(payload,"failed");if(passed+failed==0)throw new ArgumentException("Nonempty reported tests required.");next=next with{EvidenceHash=Hash(payload,"evidenceHash",64,true),Passed=passed,Failed=failed};}
  if(type is GatewayMessageType.EvidenceSubmission or GatewayMessageType.ReviewVerdict or GatewayMessageType.ApprovalRequest){if(Hash(payload,"evidenceHash",64,true)!=state.EvidenceHash)throw new InvalidOperationException("Exact reported evidence required.");}
  if(type==GatewayMessageType.ReviewVerdict){var verdict=payload.TryGetProperty("verdict",out var v)&&v.ValueKind==JsonValueKind.String?v.GetString():null;if(verdict is not ("PASS" or "FAIL")||verdict=="PASS"&&(state.Failed!=0||state.Passed is null or <=0))throw new InvalidOperationException("Bounded verdict must respect reported test failures.");next=next with{Verdict=verdict};}
  if(type==GatewayMessageType.ApprovalRequest&&state.Verdict!="PASS")throw new InvalidOperationException("Failed review cannot request acceptance.");return next;
 }
 private static string Hash(JsonElement p,string name,int length,bool upper){if(!p.TryGetProperty(name,out var v)||v.ValueKind!=JsonValueKind.String)throw new ArgumentException("Required evidence identity missing.");var s=v.GetString()!;if(s.Length!=length||s.Any(c=>!(c>='0'&&c<='9'||c>=(upper?'A':'a')&&c<=(upper?'F':'f'))))throw new ArgumentException("Bounded exact hash required.");return s;}
 private static int Count(JsonElement p,string name){if(!p.TryGetProperty(name,out var v)||v.ValueKind!=JsonValueKind.Number||!v.TryGetInt32(out var count)||count<0||count>10000)throw new ArgumentException("Bounded reported test count required.");return count;}
}
